<?php
namespace App\Http\Controllers; use App\Models\{Project,Task,User}; use Illuminate\Http\Request;
class TaskController extends Controller { private function ownProject(Project $p){abort_unless($p->user_id===auth()->id(),403);} private function own(Task $t){abort_unless($t->user_id===auth()->id(),403);} public function index(Project $project){$this->ownProject($project);return view('tasks.index',['project'=>$project,'tasks'=>$project->tasks()->withCount('members')->latest()->get()]);} public function create(Project $project){$this->ownProject($project);return view('tasks.create',['project'=>$project,'task'=>new Task]);} public function store(Request $r,Project $project){$this->ownProject($project);$d=$r->validate(['title'=>'required|max:200','description'=>'nullable','priority'=>'required|in:low,medium,high','status'=>'required|in:todo,in_progress,done','due_date'=>'nullable|date']);$d+=['project_id'=>$project->id,'user_id'=>auth()->id()];if($d['status']==='done')$d['completed_at']=now();Task::create($d);return redirect()->route('tasks.index',$project)->with('success','Tugas dibuat.');} public function show(Task $task){$this->own($task);$task->load('project','members.user');return view('tasks.show',['task'=>$task,'users'=>User::where('id','!=',auth()->id())->orderBy('name')->get()]);} public function edit(Task $task){$this->own($task);return view('tasks.create',['project'=>$task->project,'task'=>$task]);} public function update(Request $r,Task $task){$this->own($task);$d=$r->validate(['title'=>'required|max:200','description'=>'nullable','priority'=>'required|in:low,medium,high','status'=>'required|in:todo,in_progress,done','due_date'=>'nullable|date']);$d['completed_at']=$d['status']==='done'?($task->completed_at??now()):null;$task->update($d);return redirect()->route('tasks.show',$task)->with('success','Tugas diperbarui.');} public function destroy(Task $task){$this->own($task);$p=$task->project; $task->delete();return redirect()->route('tasks.index',$p)->with('success','Tugas dihapus.');} public function markAsDone(Task $task){$this->own($task);$task->markAsDone();return back()->with('success','Tugas selesai.');} }
